function validate([fruits, baskets]) {
  if (fruits.length !== baskets.length) return 'fruits and baskets must have the same length.';
  if (fruits.length < 1 || fruits.length > 100) return 'Each array needs 1 to 100 values.';
  if (fruits.some(v => v < 1 || v > 1000) || baskets.some(v => v < 1 || v > 1000)) return 'Each amount and capacity is between 1 and 1000.';
  return null;
}

