function numOfUnplacedFruits(fruits, baskets) {
  const used = new Array(baskets.length).fill(false);
  let unplaced = 0;
  for (const fruit of fruits) {
    let placed = false;
    for (let j = 0; j < baskets.length; j++) {
      if (!used[j] && baskets[j] >= fruit) {
        used[j] = true;
        placed = true;
        break;
      }
    }
    if (!placed) {
      unplaced++;
    }
  }
  return unplaced;
}

