function numOfUnplacedFruits(fruits, baskets) {
  // Keep the empty baskets in their order and remove each one as soon as it is filled.
  const free = baskets.slice();
  let placedCount = 0;
  for (const fruit of fruits) {
    const index = free.findIndex(capacity => capacity >= fruit);
    if (index !== -1) {
      free.splice(index, 1);
      placedCount++;
    }
  }
  return fruits.length - placedCount;
}

