function generate(rand, size) {
  const pick = count => Math.floor(rand() * count);
  const n = size === 'large' ? 90 + pick(11) : 1 + pick(8);
  // A narrow value range makes fruits compete for the same baskets; the full range spreads them out.
  const top = [5, 20, 1000][pick(3)];
  const fruits = Array.from({ length: n }, () => 1 + pick(top));
  const baskets = Array.from({ length: n }, () => 1 + pick(top));
  return [fruits, baskets];
}
